package io.dropwizard.jersey.optional;

import io.dropwizard.jersey.optional.exception.EmptyOptionalException;
import org.glassfish.jersey.message.MessageBodyWorkers;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyWriter;
import javax.ws.rs.ext.Provider;
import java.io.IOException;
import java.io.OutputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.util.Optional;

import static java.util.Objects.requireNonNull;

@Provider
@Produces(MediaType.WILDCARD)
public class OptionalMessageBodyWriter implements MessageBodyWriter<Optional<?>> {

    @Inject
    @Nullable
    private javax.inject.Provider<MessageBodyWorkers> mbw;

    // Jersey ignores this
    @Override
    public long getSize(Optional<?> entity, Class<?> type, Type genericType,
                        Annotation[] annotations, MediaType mediaType) {
        return 0;
    }

    @Override
    public boolean isWriteable(Class<?> type, Type genericType,
                               Annotation[] annotations, MediaType mediaType) {
        return Optional.class.isAssignableFrom(type);
    }

    @SuppressWarnings({"rawtypes", "unchecked"})
    @Override
    public void writeTo(Optional<?> entity,
                        Class<?> type,
                        Type genericType,
                        Annotation[] annotations,
                        MediaType mediaType,
                        MultivaluedMap<String, Object> httpHeaders,
                        OutputStream entityStream)
            throws IOException {
        if (!entity.isPresent()) {
            throw EmptyOptionalException.INSTANCE;
        }

        final Type innerGenericType = (genericType instanceof ParameterizedType) ?
            ((ParameterizedType) genericType).getActualTypeArguments()[0] : entity.get().getClass();

        final MessageBodyWriter writer = requireNonNull(mbw).get().getMessageBodyWriter(entity.get().getClass(),
            innerGenericType, annotations, mediaType);
        writer.writeTo(entity.get(), entity.get().getClass(),
            innerGenericType, annotations, mediaType, httpHeaders, entityStream);
    }

}

package io.dropwizard.jersey.optional.exception;

/**
 * An exception thrown when a resource endpoint attempts to write out an
 * optional that is empty.
 */
public class EmptyOptionalException extends RuntimeException {
    /**
     * Auto-generated by Eclipse.
     */
    private static final long serialVersionUID = -3398853218754085781L;

    public static final EmptyOptionalException INSTANCE = new EmptyOptionalException();

    private EmptyOptionalException() { }
}

package io.dropwizard.jersey.optional.exception;

import io.dropwizard.jersey.optional.exception.EmptyOptionalException;

import javax.ws.rs.core.Response;
import javax.ws.rs.ext.ExceptionMapper;

/**
 * The default response when an empty optional is returned, is to respond with
 * a 404 NOT FOUND response.
 */
public class EmptyOptionalExceptionMapper implements ExceptionMapper<EmptyOptionalException> {
    @Override
    public Response toResponse(EmptyOptionalException exception) {
        return Response.status(Response.Status.NOT_FOUND).build();
    }
}

package io.dropwizard.jersey.optional.exception;

import io.dropwizard.jersey.optional.exception.EmptyOptionalException;
import io.dropwizard.jersey.optional.exception.EmptyOptionalExceptionMapper;

import javax.ws.rs.core.Response;
import javax.ws.rs.ext.ExceptionMapper;
import java.util.Optional;

/**
 * Returns a 204 for {@link Optional#empty()}
 * {@link EmptyOptionalExceptionMapper} returns a 404 for {@link Optional#empty()}
 *
 * @since 2.0
 */
public class EmptyOptionalNoContentExceptionMapper implements ExceptionMapper<EmptyOptionalException> {
    @Override
    public Response toResponse(EmptyOptionalException exception) {
        return Response.noContent().build();
    }
}
